#!/usr/bin/env python3
import base64
from pathlib import Path


def decoded(value: str) -> str:
    return base64.b64decode(value.encode("ascii")).decode("utf-8")


AUDIT_FUNCTION = decoded(
    ""
)
ZENODO_BLOCK = decoded(
    ""
)
DOCS_SECTION = decoded(
    ""
)
TEST_ASSERTIONS = decoded(
    ""
)

audit_path = Path(".github/scripts/audit-published-release.sh")
audit = audit_path.read_text()
function_start = audit.index("fetch_zenodo_")
function_end = audit.index(
    "\n\n# Public GitHub release and exact asset membership.",
    function_start,
)
audit = audit[:function_start] + AUDIT_FUNCTION + audit[function_end:]

zenodo_start = audit.index("# Zenodo concept/version audit")
zenodo_end = audit.index(
    "\n# Canonical machine-readable report retained by normal CI.",
    zenodo_start,
)
audit = audit[:zenodo_start] + ZENODO_BLOCK + audit[zenodo_end:]

old_argument = '  --arg zenodoConceptDoi "$CONCEPT_DOI" \\\n'
new_arguments = (
    '  --arg zenodoSeedDoi "$ZENODO_SEED_DOI" \\\n'
    '  --arg zenodoConceptDoi "$ZENODO_CONCEPT_DOI" \\\n'
)
if old_argument in audit:
    audit = audit.replace(old_argument, new_arguments, 1)
elif new_arguments not in audit:
    raise SystemExit("unexpected Zenodo report argument state")

old_object = """    zenodo: {
      recordId: $zenodoRecordId,
      doi: $zenodoDoi,
      conceptDoi: $zenodoConceptDoi,
"""
new_object = """    zenodo: {
      seedDoi: $zenodoSeedDoi,
      recordId: $zenodoRecordId,
      doi: $zenodoDoi,
      conceptDoi: $zenodoConceptDoi,
"""
if old_object in audit:
    audit = audit.replace(old_object, new_object, 1)
elif new_object not in audit:
    raise SystemExit("unexpected Zenodo report object state")

if "conceptrecid" in audit:
    raise SystemExit("legacy conceptrecid query survived")
audit_path.write_text(audit)

test_path = Path(
    "maven-build-contract/src/test/java/de/regelsuche/build/"
    "PublishedReleaseAuditTest.java"
)
test = test_path.read_text()
test_start = test.index(
    '        assertTrue(content.contains("POLYNOMIAL_RELEASE_SMOKE_OK"));'
)
test_end = test.index(
    '        assertTrue(content.contains(\n'
    '            "regelsuche.published-release-audit/v1"));',
    test_start,
)
test = test[:test_start] + TEST_ASSERTIONS + test[test_end:]
test_path.write_text(test)

docs_path = Path("docs/published-release-audit.md")
docs = docs_path.read_text()
docs_start = docs.index("## Zenodo")
docs_end = docs.index("\n## Ergebnisartefakt", docs_start)
docs = docs[:docs_start] + DOCS_SECTION + docs[docs_end:]
docs = docs.replace(
    "Cytoscape-Version, beide Smoketests sowie Zenodo-Version, DOI, Concept DOI und\n"
    "Dateiliste.",
    "Cytoscape-Version, beide Smoketests sowie Zenodo-Seed-DOI, Versions-DOI,\n"
    "Konzept-DOI und Dateiliste.",
)
docs_path.write_text(docs)
